mapper.select:
SELECT m.num, m.USERNAME, m.NICKNAME, m.BIRTH, m.row_num, i.PROFILEIMAGE FROM (SELECT likes.*, ROW_NUMBER() OVER(ORDER BY likes.num ASC) row_num FROM (SELECT m.num, m.USERNAME, m.NICKNAME, i.PROFILEIMAGE, p.* FROM Like_REQUEST l JOIN MEMBER m ON l.REQUESTER_ID = m.nickname JOIN MEMBER_PROFILE p ON p.MEMBERID = m.num JOIN MEMBER_PROFILE_IMAGES i ON i.USERID = m.num WHERE l.RECEIVER_ID = #{nickname} AND l.STATUS = 'accepted' UNION SELECT m.num, m.USERNAME, m.NICKNAME, i.PROFILEIMAGE, p.* FROM Like_REQUEST l JOIN MEMBER m ON l.RECEIVER_ID = m.nickname JOIN MEMBER_PROFILE p ON p.MEMBERID = m.num JOIN MEMBER_PROFILE_IMAGES i ON i.USERID = m.num WHERE l.REQUESTER_ID = #{nickname} AND l.STATUS = 'accepted' ) likes
and likes.COUNTRY=#{matchingValue.country}
and likes.ADDRESS like '%'|| #{matchingValue.address} ||'%'
and likes.HEIGHT between #{matchingValue.height.low} and #{matchingValue.height.high}
and likes.WEIGHT between #{matchingValue.weight.low} and #{matchingValue.weight.high}
and likes.HOBBY like '%'|| #{matchingValue.hobby} ||'%'
and likes.MBTI like '%'|| #{matchingValue.mbti} ||'%'
and likes.RELIGION like '%'|| #{matchingValue.religion} ||'%'
and likes.DRINKING like '%'|| #{matchingValue.drinking} ||'%'
and likes.SMOKING like '%'|| #{matchingValue.smoking} ||'%'
and likes.GENDER like '%'|| #{matchingValue.gender} ||'%'
AND NICKNAME LIKE '%' || #{searchValue} || '%'
AND BIRTH BETWEEN TO_DATE(#{period.start},'YYYY') AND TO_DATE(#{period.finish} || '12-31', 'YYYY-MM-DD')
) m, ( SELECT USERID, PROFILEIMAGE FROM ( SELECT USERID, PROFILEIMAGE, ROW_NUMBER() OVER(PARTITION BY USERID ORDER BY USERID ASC) rn FROM MEMBER_PROFILE_IMAGES ) WHERE rn = 1 ) i WHERE m.num = i.USERID(+) AND m.row_num BETWEEN #{begin} AND #{end}
